#!/usr/bin/env python3
from pathlib import Path
import sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else "project")

def read(rel):
    path = root / rel
    if not path.is_file():
        raise SystemExit(f"Missing source file: {rel}")
    return path.read_text(encoding="utf-8")

def write(rel, value):
    path = root / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(value, encoding="utf-8")

client_rel = "src/main/java/com/baroxvs/client/BaroxVsClient.java"
client = read(client_rel)
if "import com.baroxvs.client.gui.ModuleClickGuiScreen;" not in client:
    client = client.replace(
        "import com.baroxvs.client.gui.BaroxMenuScreen;\n",
        "import com.baroxvs.client.gui.BaroxMenuScreen;\nimport com.baroxvs.client.gui.ModuleClickGuiScreen;\n",
        1
    )
old = "client.setScreen(new BaroxMenuScreen(CONFIG));"
if old not in client:
    raise SystemExit("Could not find the existing Right Shift menu entry point.")
client = client.replace(old, "client.setScreen(new ModuleClickGuiScreen(CONFIG));", 1)
write(client_rel, client)

write("src/main/java/com/baroxvs/client/gui/ModuleClickGuiScreen.java", "package com.baroxvs.client.gui;\n\nimport com.baroxvs.client.BaroxVsClient;\nimport com.baroxvs.client.config.BaroxConfig;\nimport com.baroxvs.client.cosmetic.ModuleCatalog;\nimport com.baroxvs.client.theme.Theme;\nimport com.baroxvs.client.theme.Themes;\nimport net.minecraft.client.MinecraftClient;\nimport net.minecraft.client.gui.DrawContext;\nimport net.minecraft.client.gui.screen.Screen;\nimport net.minecraft.text.Text;\nimport org.lwjgl.glfw.GLFW;\n\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Locale;\nimport java.util.Map;\n\n/** Animated, mobile-aware module ClickGUI. Left click toggles; right click opens settings. */\npublic final class ModuleClickGuiScreen extends Screen {\n    private enum Filter { ALL, ENABLED, DISABLED }\n    private record ModuleHit(ModuleCatalog.Module module, int x, int y, int w, int h) {}\n    private record CategoryHit(String category, int x, int y, int w, int h) {}\n\n    private final BaroxConfig cfg;\n    private final Map<String, Float> hover = new HashMap<>();\n    private final Map<String, Float> power = new HashMap<>();\n    private final List<ModuleHit> moduleHits = new ArrayList<>();\n    private final List<CategoryHit> categoryHits = new ArrayList<>();\n\n    private String selectedCategory = \"All\";\n    private String search = \"\";\n    private Filter filter = Filter.ALL;\n    private boolean searchFocused;\n    private float openProgress;\n    private float animationTime;\n    private int scroll;\n    private int maxScroll;\n    private int panelX, panelY, panelW, panelH;\n    private int sidebarW, listX, listY, listW, listBottom;\n    private int searchX, searchY, searchW, searchH;\n    private int studioX, studioY, studioW, studioH;\n    private int closeX, closeY;\n    private int allCount, enabledCount;\n\n    public ModuleClickGuiScreen(BaroxConfig cfg) {\n        super(Text.literal(\"BAROX VS ClickGUI\"));\n        this.cfg = cfg;\n    }\n\n    @Override\n    public boolean shouldPause() { return false; }\n\n    @Override\n    public void renderBackground(DrawContext context, int mouseX, int mouseY, float delta) {\n        context.fill(0, 0, width, height, 0xE8070D16);\n    }\n\n    @Override\n    public void render(DrawContext context, int mouseX, int mouseY, float delta) {\n        Theme theme = Themes.current(cfg);\n        float step = Math.max(0.01f, Math.min(1f, delta));\n        openProgress = Math.min(1f, openProgress + step * 0.13f);\n        animationTime += step;\n        layout();\n        moduleHits.clear();\n        categoryHits.clear();\n        allCount = ModuleCatalog.all().size();\n        enabledCount = 0;\n        for (ModuleCatalog.Module module : ModuleCatalog.all()) {\n            if (isEnabled(module)) enabledCount++;\n        }\n\n        drawBackdrop(context, theme);\n        drawShell(context, theme);\n        drawHeader(context, theme);\n        drawSidebar(context, theme, mouseX, mouseY);\n        drawToolbar(context, theme, mouseX, mouseY);\n        drawModules(context, theme, mouseX, mouseY, step);\n        drawFooter(context, theme);\n    }\n\n    private void layout() {\n        panelW = Math.max(250, Math.min(960, width - 12));\n        panelH = Math.max(150, Math.min(680, height - 12));\n        panelX = (width - panelW) / 2;\n        panelY = (height - panelH) / 2;\n        sidebarW = panelW < 430 ? 82 : 148;\n        int contentX = panelX + sidebarW + 13;\n        listX = contentX;\n        listW = panelX + panelW - 14 - contentX;\n        searchX = listX;\n        searchY = panelY + 54;\n        searchW = Math.max(88, listW - 138);\n        searchH = 27;\n        listY = searchY + 39;\n        listBottom = panelY + panelH - 27;\n        studioW = 62;\n        studioH = 22;\n        studioX = panelX + panelW - 112;\n        studioY = panelY + 10;\n        closeX = panelX + panelW - 35;\n        closeY = panelY + 10;\n    }\n\n    private void drawBackdrop(DrawContext c, Theme theme) {\n        c.fillGradient(0, 0, width, height, 0xF4060A12, 0xF00B1421);\n        int glow = Ui.alpha(theme.primary(), 0x12);\n        for (int i = 0; i < 9; i++) {\n            float phase = animationTime * (0.23f + i * 0.018f) + i * 1.73f;\n            int x = (int) ((width * 0.5) + Math.sin(phase) * width * 0.42);\n            int y = (int) ((height * 0.5) + Math.cos(phase * 0.81f) * height * 0.42);\n            int size = 2 + (i % 3);\n            c.fill(x, y, x + size, y + size, glow);\n        }\n    }\n\n    private void drawShell(DrawContext c, Theme theme) {\n        int lift = Math.round((1f - openProgress) * 18f);\n        Ui.glassPanel(c, panelX, panelY + lift, panelX + panelW, panelY + panelH + lift,\n                18, 0xF20C1520, Ui.alpha(theme.primary(), 0x96));\n        Ui.roundRect(c, panelX + 1, panelY + 1 + lift, panelX + panelW - 1,\n                panelY + 43 + lift, 14, 0xAA172535);\n        c.fill(panelX + 18, panelY + 43 + lift, panelX + panelW - 18, panelY + 44 + lift,\n                Ui.alpha(theme.primary(), 0x4C));\n        Ui.glassPanel(c, panelX + 8, panelY + 49 + lift, panelX + sidebarW + 3,\n                panelY + panelH - 9 + lift, 12, 0xB80A111A, 0x303B5263);\n    }\n\n    private void drawHeader(DrawContext c, Theme theme) {\n        int y = panelY + 11 + Math.round((1f - openProgress) * 18f);\n        Ui.text(c, textRenderer, \"BAROX\", panelX + 17, y, theme.primary(), 1.02f, true);\n        Ui.text(c, textRenderer, \"VS\", panelX + 60, y, 0xFFF3F7FC, 1.02f, true);\n        Ui.text(c, textRenderer, \"MODULE INTERFACE\", panelX + 88, y + 3, 0xFF8297A9, 0.58f, true);\n        Ui.roundRect(c, studioX, studioY, studioX + studioW, studioY + studioH, 8, 0xA52A4050);\n        Ui.textCentered(c, textRenderer, \"STUDIO\", studioX + studioW / 2, studioY + 7,\n                0xFFDAE8F0, 0.57f, true);\n        Ui.roundRect(c, closeX, closeY, closeX + 23, closeY + studioH, 8, 0xA63B2934);\n        Ui.textCentered(c, textRenderer, \"×\", closeX + 11, closeY + 5, 0xFFFFD6E1, 0.88f, true);\n    }\n\n    private void drawSidebar(DrawContext c, Theme theme, int mouseX, int mouseY) {\n        List<String> categories = new ArrayList<>();\n        categories.add(\"All\");\n        categories.addAll(ModuleCatalog.categories());\n        int y = panelY + 64;\n        int rowH = panelH < 270 ? 25 : 31;\n        for (String category : categories) {\n            int x = panelX + 14;\n            int w = sidebarW - 14;\n            boolean selected = selectedCategory.equals(category);\n            boolean over = inside(mouseX, mouseY, x, y, w, rowH - 3);\n            String key = \"cat:\" + category;\n            float value = approach(hover.getOrDefault(key, 0f), over ? 1f : 0f, 0.24f);\n            hover.put(key, value);\n            if (selected) {\n                Ui.glassPanel(c, x, y, x + w, y + rowH - 3, 8,\n                        Ui.alpha(theme.primary(), 0x30), Ui.alpha(theme.primary(), 0xA0));\n            } else if (value > 0.01f) {\n                Ui.roundRect(c, x, y, x + w, y + rowH - 3, 8,\n                        Ui.alpha(theme.primary(), Math.round(value * 0x20)));\n            }\n            String label = category.equals(\"All\") ? \"OVERVIEW\" :\n                    (panelW < 430 ? compactCategory(category) : category.toUpperCase(Locale.ROOT));\n            Ui.text(c, textRenderer, Ui.fit(textRenderer, label, w - 12, 0.61f),\n                    x + 7, y + 7, selected ? 0xFFF5FAFF : 0xFF9FB1BF, 0.61f, selected);\n            int count = countCategory(category);\n            Ui.textRight(c, textRenderer, Integer.toString(count), x + w - 6, y + 7,\n                    selected ? theme.primary() : 0xFF647A89, 0.55f, true);\n            categoryHits.add(new CategoryHit(category, x, y, w, rowH - 3));\n            y += rowH;\n        }\n        int footerY = panelY + panelH - 43;\n        Ui.text(c, textRenderer, \"BUILD 021\", panelX + 17, footerY, 0xFF748A99, 0.55f, true);\n        Ui.text(c, textRenderer, \"78 MODULES\", panelX + 17, footerY + 11, 0xFF526675, 0.52f, false);\n    }\n\n    private String compactCategory(String category) {\n        return switch (category) {\n            case \"Cosmetics\" -> \"STYLE\";\n            case \"Effects\" -> \"FX\";\n            case \"Trails\" -> \"TRAILS\";\n            case \"HUD\" -> \"HUD\";\n            case \"Misc\" -> \"MISC\";\n            default -> category.toUpperCase(Locale.ROOT);\n        };\n    }\n\n    private int countCategory(String category) {\n        if (category.equals(\"All\")) return ModuleCatalog.all().size();\n        return ModuleCatalog.inCategory(category).size();\n    }\n\n    private void drawToolbar(DrawContext c, Theme theme, int mouseX, int mouseY) {\n        Ui.glassPanel(c, searchX, searchY, searchX + searchW, searchY + searchH,\n                8, searchFocused ? 0xD11C2D3A : 0xA614222D,\n                searchFocused ? Ui.alpha(theme.primary(), 0xCC) : 0x48526878);\n        String shown = search.isEmpty() ? (searchFocused ? \"\" : \"Search modules...\") : search;\n        Ui.text(c, textRenderer, shown, searchX + 9, searchY + 9,\n                search.isEmpty() ? 0xFF738997 : 0xFFE7F0F5, 0.66f, false);\n        if (searchFocused && (animationTime % 1.0f) < 0.55f) {\n            int caret = searchX + 9 + textRenderer.getWidth(search) / 2;\n            c.fill(Math.min(searchX + searchW - 8, caret), searchY + 8,\n                    Math.min(searchX + searchW - 7, caret) + 1, searchY + 19, theme.primary());\n        }\n        int fx = searchX + searchW + 6;\n        int fy = searchY + 1;\n        String[] labels = {\"ALL\", \"ON\", \"OFF\"};\n        Filter[] values = Filter.values();\n        int chipW = Math.max(32, (listW - searchW - 12) / 3);\n        for (int i = 0; i < values.length; i++) {\n            int x = fx + i * (chipW + 2);\n            boolean selected = filter == values[i];\n            boolean over = inside(mouseX, mouseY, x, fy, chipW, searchH - 2);\n            Ui.roundRect(c, x, fy, x + chipW, fy + searchH - 2, 7,\n                    selected ? Ui.alpha(theme.primary(), 0x55) : (over ? 0x80384C5C : 0x6620313E));\n            Ui.textCentered(c, textRenderer, labels[i], x + chipW / 2, fy + 9,\n                    selected ? 0xFFF4FAFF : 0xFF94A7B4, 0.56f, true);\n        }\n        int shownCount = filteredModules().size();\n        Ui.text(c, textRenderer, \"MODULES\", listX + 2, searchY + 34,\n                0xFFDDE8EF, 0.62f, true);\n        Ui.textRight(c, textRenderer, shownCount + \" / \" + allCount,\n                listX + listW, searchY + 34, 0xFF718798, 0.56f, true);\n    }\n\n    private void drawModules(DrawContext c, Theme theme, int mouseX, int mouseY, float delta) {\n        List<ModuleCatalog.Module> modules = filteredModules();\n        boolean twoColumns = listW >= 430;\n        int gap = 8;\n        int columns = twoColumns ? 2 : 1;\n        int cardW = (listW - gap * (columns - 1)) / columns;\n        int cardH = panelH < 250 ? 43 : 54;\n        int rowGap = 7;\n        int rows = (modules.size() + columns - 1) / columns;\n        int contentHeight = rows * (cardH + rowGap);\n        maxScroll = Math.max(0, contentHeight - Math.max(1, listBottom - listY));\n        scroll = Math.max(0, Math.min(maxScroll, scroll));\n        c.enableScissor(listX, listY, listX + listW, listBottom);\n        for (int i = 0; i < modules.size(); i++) {\n            ModuleCatalog.Module module = modules.get(i);\n            int col = i % columns;\n            int row = i / columns;\n            int x = listX + col * (cardW + gap);\n            int y = listY + row * (cardH + rowGap) - scroll;\n            if (y + cardH < listY || y > listBottom) continue;\n            drawModuleCard(c, theme, module, x, y, cardW, cardH, mouseX, mouseY, delta);\n        }\n        c.disableScissor();\n        if (modules.isEmpty()) {\n            Ui.textCentered(c, textRenderer, \"NO MATCHING MODULES\", listX + listW / 2,\n                    listY + 38, 0xFF7C91A0, 0.7f, true);\n            Ui.textCentered(c, textRenderer, \"Try another search or filter\",\n                    listX + listW / 2, listY + 54, 0xFF627786, 0.59f, false);\n        }\n        if (maxScroll > 0) {\n            int trackX = listX + listW - 2;\n            int trackH = listBottom - listY - 8;\n            int thumbH = Math.max(18, Math.round(trackH * (trackH / (float) contentHeight)));\n            int thumbY = listY + 4 + Math.round((trackH - thumbH) * (scroll / (float) maxScroll));\n            Ui.roundRect(c, trackX, listY + 4, trackX + 2, listBottom - 4, 2, 0x44394C5B);\n            Ui.roundRect(c, trackX - 1, thumbY, trackX + 3, thumbY + thumbH, 2,\n                    Ui.alpha(theme.primary(), 0xCC));\n        }\n    }\n\n    private void drawModuleCard(DrawContext c, Theme theme, ModuleCatalog.Module module,\n                                int x, int y, int w, int h, int mouseX, int mouseY, float delta) {\n        boolean enabled = isEnabled(module);\n        boolean over = inside(mouseX, mouseY, x, y, w, h);\n        float hoverValue = approach(hover.getOrDefault(module.id(), 0f), over ? 1f : 0f, Math.min(0.48f, delta * 0.42f));\n        float powerValue = approach(power.getOrDefault(module.id(), enabled ? 1f : 0f),\n                enabled ? 1f : 0f, Math.min(0.42f, delta * 0.34f));\n        hover.put(module.id(), hoverValue);\n        power.put(module.id(), powerValue);\n\n        int base = enabled ? 0xB3213540 : 0x9B111E29;\n        Ui.glassPanel(c, x, y, x + w, y + h, 9,\n                over ? Ui.alpha(theme.primary(), Math.round(0x20 + hoverValue * 0x24)) : base,\n                enabled ? Ui.alpha(theme.primary(), 0x68) : Ui.alpha(theme.primary(), Math.round(0x1E + hoverValue * 0x32)));\n        int barHeight = Math.max(2, Math.round((h - 14) * powerValue));\n        Ui.roundRect(c, x + 5, y + (h - barHeight) / 2, x + 7, y + (h + barHeight) / 2,\n                2, Ui.alpha(theme.primary(), Math.round(0x44 + powerValue * 0xBB)));\n\n        int right = x + w - 10;\n        String state = module.kind() == ModuleCatalog.Kind.CYCLE ? \"STYLE\" : (enabled ? \"ON\" : \"OFF\");\n        int pillW = 37;\n        Ui.roundRect(c, right - pillW, y + 8, right, y + 23, 6,\n                enabled ? Ui.alpha(theme.primary(), Math.round(0x35 + powerValue * 0x32)) : 0x78334350);\n        Ui.textCentered(c, textRenderer, state, right - pillW / 2, y + 13,\n                enabled ? theme.primary() : 0xFF8396A3, 0.54f, true);\n\n        int textX = x + 14;\n        int textW = w - 70;\n        Ui.text(c, textRenderer, Ui.fit(textRenderer, module.name(), textW, 0.72f),\n                textX, y + 9, enabled ? 0xFFF5FAFE : 0xFFD4E0E7, 0.72f, true);\n        if (h > 45) {\n            Ui.text(c, textRenderer, Ui.fit(textRenderer, module.description(), textW, 0.55f),\n                    textX, y + 27, 0xFF8195A4, 0.55f, false);\n            String hint = module.hasOptions() ? module.options().length + \" STYLES  ·  RMB SETTINGS\" : \"RMB SETTINGS\";\n            Ui.textRight(c, textRenderer, hint, right, y + h - 12, 0xFF627987, 0.49f, true);\n        }\n        moduleHits.add(new ModuleHit(module, x, y, w, h));\n    }\n\n    private void drawFooter(DrawContext c, Theme theme) {\n        Ui.text(c, textRenderer, \"LMB  TOGGLE     RMB  SETTINGS     WHEEL  SCROLL\",\n                listX + 1, panelY + panelH - 20, 0xFF708594, 0.53f, true);\n        int barW = Math.max(0, Math.min(listW, Math.round(listW * openProgress)));\n        if (barW > 0) c.fill(listX, panelY + panelH - 7, listX + barW, panelY + panelH - 6,\n                Ui.alpha(theme.primary(), 0xB0));\n    }\n\n    private List<ModuleCatalog.Module> filteredModules() {\n        List<ModuleCatalog.Module> out = new ArrayList<>();\n        List<ModuleCatalog.Module> source = selectedCategory.equals(\"All\")\n                ? ModuleCatalog.all() : ModuleCatalog.inCategory(selectedCategory);\n        String needle = search.trim().toLowerCase(Locale.ROOT);\n        for (ModuleCatalog.Module module : source) {\n            boolean enabled = isEnabled(module);\n            if (filter == Filter.ENABLED && !enabled) continue;\n            if (filter == Filter.DISABLED && enabled) continue;\n            if (!needle.isEmpty() && !(module.name().toLowerCase(Locale.ROOT).contains(needle)\n                    || module.description().toLowerCase(Locale.ROOT).contains(needle)\n                    || module.id().toLowerCase(Locale.ROOT).contains(needle))) continue;\n            out.add(module);\n        }\n        return out;\n    }\n\n    private boolean isEnabled(ModuleCatalog.Module module) {\n        return module.kind() == ModuleCatalog.Kind.CYCLE || cfg.isOn(module.id());\n    }\n\n    private static float approach(float current, float target, float factor) {\n        return current + (target - current) * Math.max(0.02f, Math.min(1f, factor));\n    }\n\n    private static boolean inside(double mx, double my, int x, int y, int w, int h) {\n        return mx >= x && mx <= x + w && my >= y && my <= y + h;\n    }\n\n    @Override\n    public boolean mouseClicked(double mouseX, double mouseY, int button) {\n        if (inside(mouseX, mouseY, closeX, closeY, 23, studioH)) {\n            close();\n            return true;\n        }\n        if (inside(mouseX, mouseY, studioX, studioY, studioW, studioH) && button == 0) {\n            client.setScreen(new BaroxMenuScreen(cfg));\n            return true;\n        }\n        if (inside(mouseX, mouseY, searchX, searchY, searchW, searchH) && button == 0) {\n            searchFocused = true;\n            return true;\n        }\n        searchFocused = false;\n        int fx = searchX + searchW + 6;\n        int chipW = Math.max(32, (listW - searchW - 12) / 3);\n        if (button == 0 && mouseY >= searchY && mouseY <= searchY + searchH) {\n            for (int i = 0; i < Filter.values().length; i++) {\n                int x = fx + i * (chipW + 2);\n                if (inside(mouseX, mouseY, x, searchY + 1, chipW, searchH - 2)) {\n                    filter = Filter.values()[i];\n                    scroll = 0;\n                    return true;\n                }\n            }\n        }\n        if (button == 0) {\n            for (CategoryHit hit : categoryHits) {\n                if (inside(mouseX, mouseY, hit.x(), hit.y(), hit.w(), hit.h())) {\n                    selectedCategory = hit.category();\n                    scroll = 0;\n                    return true;\n                }\n            }\n        }\n        for (ModuleHit hit : moduleHits) {\n            if (!inside(mouseX, mouseY, hit.x(), hit.y(), hit.w(), hit.h())) continue;\n            ModuleCatalog.Module module = hit.module();\n            if (button == 1) {\n                client.setScreen(new ModuleSettingsScreen(this, cfg, module));\n                return true;\n            }\n            if (button == 0) {\n                if (module.kind() == ModuleCatalog.Kind.CYCLE) {\n                    cfg.cycleStyle(module.id());\n                    cfg.save();\n                } else {\n                    BaroxVsClient.toggleModule(module.id());\n                }\n                return true;\n            }\n        }\n        return super.mouseClicked(mouseX, mouseY, button);\n    }\n\n    @Override\n    public boolean mouseScrolled(double mouseX, double mouseY, double horizontalAmount, double verticalAmount) {\n        if (mouseX >= listX && mouseX <= listX + listW && mouseY >= listY && mouseY <= listBottom && maxScroll > 0) {\n            scroll = Math.max(0, Math.min(maxScroll, scroll - (int) Math.round(verticalAmount * 42)));\n            return true;\n        }\n        return super.mouseScrolled(mouseX, mouseY, horizontalAmount, verticalAmount);\n    }\n\n    @Override\n    public boolean charTyped(char chr, int modifiers) {\n        if (searchFocused && !Character.isISOControl(chr) && search.length() < 40) {\n            search += chr;\n            scroll = 0;\n            return true;\n        }\n        return super.charTyped(chr, modifiers);\n    }\n\n    @Override\n    public boolean keyPressed(int keyCode, int scanCode, int modifiers) {\n        if (keyCode == GLFW.GLFW_KEY_ESCAPE) {\n            if (searchFocused) {\n                searchFocused = false;\n                return true;\n            }\n            close();\n            return true;\n        }\n        if (searchFocused && keyCode == GLFW.GLFW_KEY_BACKSPACE && !search.isEmpty()) {\n            search = search.substring(0, search.length() - 1);\n            scroll = 0;\n            return true;\n        }\n        if (!searchFocused && keyCode == GLFW.GLFW_KEY_SLASH) {\n            searchFocused = true;\n            return true;\n        }\n        if (searchFocused && keyCode == GLFW.GLFW_KEY_ENTER) {\n            searchFocused = false;\n            return true;\n        }\n        return super.keyPressed(keyCode, scanCode, modifiers);\n    }\n\n    @Override\n    public void close() {\n        cfg.save();\n        if (client != null) client.setScreen(null);\n    }\n}\n")
print("Applied v021: animated module ClickGUI with category navigation, live search, state filters, left-click toggle and right-click settings.")
